function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function loadStatement(format){const formEl=document.getElementById('cu-statement'),fields=Object.fromEntries(new FormData(formEl));const q=new URLSearchParams(Object.fromEntries(Object.entries({...fields,format:format==='print'?'print':format}).filter(([,v])=>v)));const r=await api('customers/'+profile.id+'/statement?'+q);if(['csv','excel'].includes(format))download(new Blob([r.data],{type:r.mime}),r.filename);else{statement=r;redraw();if(format==='print')window.print();}}
function notificationHTML(){queueMicrotask(async()=>{try{const rows=(await api('notifications')).rows;if(app.state.currentPage!=='notifications')return;const n=document.getElementById('cu-central-notifications');if(n)n.innerHTML=table([t('التاريخ','Date'),t('الحدث','Event'),t('الشركة','Company'),t('فتح','Open')],rows.map(r=>[e(r.createdAt),e(r.action),e(r.companyId),r.source==='personnel'?`<button type="button" class="ghost-btn" data-notice-personnel="${e(r.entityId)}">${t('شؤون الموظفين والمهام','Personnel & tasks')}</button>`:r.source==='ledger'?`<button type="button" class="ghost-btn" data-notice-ledger="${e(r.companyId)}">${t('الإدارة المالية','Financial management')}</button>`:r.source==='customer'?`<button type="button" class="ghost-btn" data-notice-customer="${e(r.entityId)}">${t('ملف العميل','Customer profile')}</button>`:r.source==='vehicle'?`<button type="button" class="ghost-btn" data-notice-vehicle="${e(r.entityId)}">${t('المركبة / الطلب','Vehicle / request')}</button>`:e(r.entityId)]));n?.querySelectorAll('[data-notice-personnel]').forEach(b=>b.onclick=()=>PersonnelUI.openNotification(b.dataset.noticePersonnel));n?.querySelectorAll('[data-notice-ledger]').forEach(b=>b.onclick=()=>LedgerUI.openNotification(b.dataset.noticeLedger));n?.querySelectorAll('[data-notice-vehicle]').forEach(b=>b.onclick=()=>VehicleUI.openNotification(b.dataset.noticeVehicle));n?.querySelectorAll('[data-notice-customer]').forEach(b=>b.onclick=async()=>{app.state.currentPage='customers';if(!cap)await load();await open(b.dataset.noticeCustomer);});}catch{}});return '<section class="content-panel"><h2>'+t('الإشعارات المركزية','Central notifications')+'</h2><div id="cu-central-notifications"></div></section>';}
async function openRecord(id){const who=ABCentral?.actor?.id;if(actor!==who){reset();actor=who;}if(!cap)await load();app.state.currentPage='customers';await open(id);}
async function openCompany(id){const who=ABCentral?.actor?.id;if(actor!==who){reset();actor=who;}if(!cap)await load();{const grid=JSON.parse(filters.grid||'{}');grid.values={...grid.values,companyId:[id]};filters={...filters,grid:JSON.stringify(grid)};}profile=null;editing=null;tab='list';app.state.currentPage='customers';await fetchRows(true);redraw();}
